//! @generated by xtask split-cards.
use super::prelude::*;

/// Metamorphosis.cs OnPlay: create 3 (upgraded: 5) character-pool Attacks
/// with replacement, SetToFreeThisCombat, then add each to Draw at Random.
/// CardFactory.GetForCombat creates the whole list before insertion.
/// CardModel.SetToFreeThisCombat sets both energy and star costs; use the
/// existing Touch of Insanity representation, including upgrade protection.
/// CardEnergyCost.GetWithModifiers bypasses local modifiers for X costs.
pub(crate) fn play_metamorphosis(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    let Some(character) = state.player.character else {
        return EffectResult::Resolved;
    };
    let count = if current_upgraded(state) { 5 } else { 3 };
    let uids = create_character_cards_into_arena(
        state,
        character,
        count,
        Some(sts2_core::cards::CardType::Attack),
        false,
    );
    for uid in uids {
        let card = &mut state.cards[uid.0.get() as usize - 1];
        if !card.is_x_cost() {
            card.cost = 0;
        }
        card.set_combat_var(VarKey::StarCostFreeThisCombat, 1);
        card.set_combat_var(VarKey::CostAbsolutelySet, 1);
        state.player.generated_cards_this_combat =
            state.player.generated_cards_this_combat.saturating_add(1);
        let len = state.player.draw.len();
        let insert_at = state.run_rng.shuffle.next_int(0, len as i32) as usize;
        state.player.draw.insert(insert_at, uid);
        sts2_core::card_effects::fire_card_generation_listeners(
            state,
            uid,
            sts2_core::card_effects::PileKind::Draw,
            true,
        );
    }
    EffectResult::Resolved
}
